@startuml
class Kinepolis {}
class Cinema {
  +town: string
}
class Theatre {
  +theatreNumber: int
}
class Movie {}
class MovieCopy {}
class Show {
  +startTime: datetime
}
class Reservation {
  +reservationTime: datetime
}
class CreditCard {}
class Seat {
  +seatNumber: string
}
class Ticket {
  +isAnonymous: boolean
}
class Offer {
  +expiryTime: datetime
}

Kinepolis "1" -- "*" Cinema : owns
Cinema "1" *-- "*" Theatre : has
Cinema "1" -- "*" MovieCopy : owns
Theatre "1" -- "*" Show : hosts
Movie "1" -- "*" MovieCopy : is played by
Show "1" -- "*" Reservation : has
Show "1" -- "*" Ticket : issues
Show "1" -- "*" Offer : generates
Show "1" -- "*" Show : offers alternative for
Reservation "1" -- "1" Seat : reserves
Reservation "1" -- "1" CreditCard : paid with
Ticket "1" -- "1" Seat : assigned
Ticket "1" -- "1" Show : for
@enduml

